// Usage: go run scripts/rewrite-go-functions.go FILE NAME BODYFILE (NAME=- deletes receiver methods).
package main
import("go/parser";"go/token";"go/ast";"os";"sort")
func main(){p:=os.Args[1];name:=os.Args[2];s,e:=os.ReadFile(p);if e!=nil{panic(e)};set:=token.NewFileSet();f,e:=parser.ParseFile(set,p,s,0);if e!=nil{panic(e)};type edit struct{a,b int;v []byte};var edits []edit;for _,d:=range f.Decls{fn,ok:=d.(*ast.FuncDecl);if !ok{continue};if name=="-"&&fn.Recv!=nil{edits=append(edits,edit{set.Position(fn.Pos()).Offset,set.Position(fn.End()).Offset,nil})};if fn.Name.Name==name{body,e:=os.ReadFile(os.Args[3]);if e!=nil{panic(e)};edits=append(edits,edit{set.Position(fn.Body.Pos()).Offset+1,set.Position(fn.Body.End()).Offset-1,body})}};if len(edits)==0{panic("no matching function: "+name)};sort.Slice(edits,func(i,j int)bool{return edits[i].a>edits[j].a});for _,e:=range edits{s=append(append(append([]byte{},s[:e.a]...),e.v...),s[e.b:]...)};if e=os.WriteFile(p,s,0644);e!=nil{panic(e)}}
